import math

def transform(inp: str) -> list[str]:
    lines = inp.strip().split('\n')
    n = int(lines[0])

    # Parse the polygon points
    points = [tuple(map(int, line.split())) for line in lines[1:]]

    # Helper functions to apply transformations
    def translate(dx, dy):
        return '\n'.join([str(n)] + [f"{x + dx} {y + dy}" for x, y in points])

    def rotate_90():
        return '\n'.join([str(n)] + [f"{-y} {x}" for x, y in points])

    def reflect_x():
        return '\n'.join([str(n)] + [f"{x} {-y}" for x, y in points])

    def reflect_y():
        return '\n'.join([str(n)] + [f"{-x} {y}" for x, y in points])

    def rotate_180():
        return '\n'.join([str(n)] + [f"{-x} {-y}" for x, y in points])

    def rotate_270():
        return '\n'.join([str(n)] + [f"{y} {-x}" for x, y in points])

    def reverse_order():
        return '\n'.join([str(n)] + [f"{x} {y}" for x, y in reversed(points)])

    def rotate_clockwise(angle_degrees):
        # Rotate all points around the origin by angle_degrees
        angle_rad = math.radians(angle_degrees)
        cos_theta = math.cos(angle_rad)
        sin_theta = math.sin(angle_rad)
        return '\n'.join([str(n)] + [
            f"{int(x * cos_theta - y * sin_theta)} {int(x * sin_theta + y * cos_theta)}"
            for x, y in points
        ])

    # Generate transformations
    transformations = [
        translate(100, 100),
        rotate_90(),
        rotate_180(),
        rotate_270(),
        reflect_x(),
        reflect_y(),
        reverse_order(),
        rotate_clockwise(90),
        rotate_clockwise(180),
        rotate_clockwise(270),
    ]

    # Filter out duplicates by comparing string representations
    unique_transformations = []
    for t in transformations:
        if t not in unique_transformations:
            unique_transformations.append(t)

    return unique_transformations[:4]
